// Config plugin: settings this project needs to build its Android APK locally on Windows, and to
// sign release builds with the app's own key.
// android/ is regenerated by `expo prebuild`, so these live here instead of in the generated files.
const fs = require('fs');
const path = require('path');
const { withAppBuildGradle, withDangerousMod, withGradleProperties } = require('expo/config-plugins');

// R8 keep rules the release build needs, appended to android/app/proguard-rules.pro.
// WorkManager (used by expo-background-task for the presence check-in) builds its Room database by
// reflection; R8 full mode strips the generated constructor and the app crashes on start with
// "NoSuchMethodException: androidx.work.impl.WorkDatabase_Impl.<init>" (found on a phone 2026-11-23).
const PROGUARD_MARKER = '# FlatApp: WorkManager / Room';
const PROGUARD_RULES = [
  PROGUARD_MARKER,
  '-keep class * extends androidx.room.RoomDatabase { <init>(); }',
  '-keep class * extends androidx.work.ListenableWorker { <init>(android.content.Context, androidx.work.WorkerParameters); }',
  '',
].join('\n');

// arm64-v8a for real phones, x86_64 for the emulator. Skipping the 32-bit ABIs halves build time.
const ARCHITECTURES = 'arm64-v8a,x86_64';

// Libraries with native screen components (react-native-screens, safe-area-context) compile object
// files at paths over 300 characters. That needs Windows long paths switched on (LongPathsEnabled=1)
// AND a ninja that is long-path aware: CMake 3.22's ninja 1.10 is not, CMake 3.31's ninja 1.12 is.
const CMAKE_VERSION = '3.31.6';

function withArchitectures(config) {
  return withGradleProperties(config, (cfg) => {
    const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === 'reactNativeArchitectures');
    if (existing) {
      existing.value = ARCHITECTURES;
    } else {
      cfg.modResults.push({ type: 'property', key: 'reactNativeArchitectures', value: ARCHITECTURES });
    }
    return cfg;
  });
}

function withCmakeVersion(config) {
  return withAppBuildGradle(config, (cfg) => {
    const gradle = cfg.modResults;
    if (gradle.contents.includes(`version "${CMAKE_VERSION}"`)) return cfg;
    const block = [
      '',
      '    externalNativeBuild {',
      '        cmake {',
      `            version "${CMAKE_VERSION}"`,
      '        }',
      '    }',
    ].join('\n');
    const next = gradle.contents.replace(/(\nandroid\s*\{)/, `$1${block}`);
    if (next === gradle.contents) {
      throw new Error('withLocalAndroidBuild: android { } block not found in app/build.gradle');
    }
    gradle.contents = next;
    return cfg;
  });
}

function withProguardRules(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (!current.includes(PROGUARD_MARKER)) {
        fs.writeFileSync(file, `${current.replace(/\s*$/, '\n')}\n${PROGUARD_RULES}`);
      }
      return cfg;
    },
  ]);
}

// Release builds are signed with FlatApp's own key, never the public React Native debug key: security
// apps flag anything signed with that one (Sophos: PUA "App/Other/Android Abused Certificate",
// 2026-11-23). The key file and its password live outside the project, in the user-level
// ~/.gradle/gradle.properties written by scripts/create-release-key.ps1, so neither reaches git.
// Without them a release build stops with an error instead of quietly falling back to the debug key.
const SIGNING_MARKER = 'FLATAPP_UPLOAD_STORE_FILE';
const SIGNING_CONFIG = `
        release {
            // FlatApp's own key: values from ~/.gradle/gradle.properties (see README, "Signing").
            if (project.hasProperty('FLATAPP_UPLOAD_STORE_FILE')) {
                storeFile file(FLATAPP_UPLOAD_STORE_FILE)
                storePassword FLATAPP_UPLOAD_STORE_PASSWORD
                keyAlias FLATAPP_UPLOAD_KEY_ALIAS
                keyPassword FLATAPP_UPLOAD_KEY_PASSWORD
            }
        }`;
const SIGNING_GUARD = `
// FlatApp: refuse to build a release APK without the app's own key (see README, "Signing").
gradle.taskGraph.whenReady { graph ->
    def releaseTask = graph.allTasks.any { it.project == project && (it.name == 'assembleRelease' || it.name == 'bundleRelease') }
    if (releaseTask && !project.hasProperty('FLATAPP_UPLOAD_STORE_FILE')) {
        throw new GradleException("FlatApp's release key is not set up on this PC: FLATAPP_UPLOAD_* is missing from ~/.gradle/gradle.properties. Run scripts/create-release-key.ps1 once (see README, Signing).")
    }
}
`;

function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    const gradle = cfg.modResults;
    if (gradle.contents.includes(SIGNING_MARKER)) return cfg;
    let next = gradle.contents.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig project.hasProperty('${SIGNING_MARKER}') ? signingConfigs.release : signingConfigs.debug`,
    );
    next = next.replace(/(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/, `$1${SIGNING_CONFIG}`);
    if (!next.includes(`storeFile file(${SIGNING_MARKER})`) || !next.includes('signingConfigs.release :')) {
      throw new Error('withLocalAndroidBuild: signingConfigs / buildTypes.release not found in app/build.gradle');
    }
    gradle.contents = `${next.replace(/\s*$/, '\n')}${SIGNING_GUARD}`;
    return cfg;
  });
}

module.exports = function withLocalAndroidBuild(config) {
  return withReleaseSigning(withProguardRules(withCmakeVersion(withArchitectures(config))));
};
